item.text:
{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM 明确参与组织检查，并作为通知接收者；并非仅出现角色名称。",
      "sources": [
        {"quote": "请 PM 组织检查 service.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "“请”提出组织检查的要求，组织是主句动作。",
      "sources": [
        {"quote": "请 PM 组织检查 service.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "check",
      "verdict": "SUPPORT",
      "reason": "检查是组织动作的补语；未独立指定检查执行者，也未将其提升为独立主句要求。",
      "sources": [
        {"quote": "组织检查 service.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "log",
      "verdict": "SUPPORT",
      "reason": "service.log 是待检查的现有文件，没有生成或修改该文件的要求。",
      "sources": [
        {"quote": "检查 service.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "critical_error",
      "verdict": "SUPPORT",
      "reason": "critical 错误是条件中被发现的对象。",
      "sources": [
        {"quote": "若发现 critical 错误", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "found",
      "verdict": "SUPPORT",
      "reason": "发现错误被用作条件成立状态，没有被表达为独立执行义务。",
      "sources": [
        {"quote": "若发现 critical 错误", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "stop",
      "verdict": "SUPPORT",
      "reason": "发现 critical 错误时，停止任务是明确的条件性强制要求。",
      "sources": [
        {"quote": "若发现 critical 错误，任务必须立即停止", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "immediate",
      "verdict": "SUPPORT",
      "reason": "“立即”明确约束停止动作的时机。",
      "sources": [
        {"quote": "任务必须立即停止", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "notify",
      "verdict": "SUPPORT",
      "reason": "通知与停止并列，共享发现错误的条件和“必须”的要求；没有明确通知执行者。",
      "sources": [
        {"quote": "若发现 critical 错误，任务必须立即停止并通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "generate",
      "verdict": "SUPPORT",
      "reason": "“否则应形成”表达另一条件分支中的产出要求。",
      "sources": [
        {"quote": "否则应形成 service-summary.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "summary",
      "verdict": "SUPPORT",
      "reason": "service-summary.md 是否则分支中要求形成的文件，适合标记为条件性输出。",
      "sources": [
        {"quote": "否则应形成 service-summary.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "restart",
      "verdict": "SUPPORT",
      "reason": "“不得”明确禁止重启；肯定动作内容配合 FORBIDDEN 表达禁止，不是要求执行重启。",
      "sources": [
        {"quote": "不得重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "service",
      "verdict": "SUPPORT",
      "reason": "服务是禁止重启动作的对象。",
      "sources": [
        {"quote": "不得重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_organizer",
      "verdict": "SUPPORT",
      "reason": "PM 是组织动作的明确参与者；该关系没有推断 PM 亲自检查。",
      "sources": [
        {"quote": "PM 组织检查 service.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_check_complement",
      "verdict": "SUPPORT",
      "reason": "“组织检查”支持检查作为组织事件的补语组成部分。",
      "sources": [
        {"quote": "组织检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_checked_log",
      "verdict": "SUPPORT",
      "reason": "service.log 是检查动作的对象；PATIENT 本身不意味着修改文件。",
      "sources": [
        {"quote": "检查 service.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_discovered_error",
      "verdict": "SUPPORT",
      "reason": "发现状态的主题明确为 critical 错误。",
      "sources": [
        {"quote": "发现 critical 错误", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_stop_condition",
      "verdict": "SUPPORT",
      "reason": "发现错误是停止任务的条件，不是完成条件。",
      "sources": [
        {"quote": "若发现 critical 错误，任务必须立即停止", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_stop_task",
      "verdict": "SUPPORT",
      "reason": "明确停止的是当前任务，TASK 绑定有“任务”的文字依据。",
      "sources": [
        {"quote": "任务必须立即停止", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_immediate_stop",
      "verdict": "SUPPORT",
      "reason": "立即性明确约束停止；该正向关系不排除立即性也可能覆盖通知。",
      "sources": [
        {"quote": "立即停止并通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_notify_condition",
      "verdict": "SUPPORT",
      "reason": "并列通知动作共享“若发现 critical 错误”的前提。",
      "sources": [
        {"quote": "若发现 critical 错误，任务必须立即停止并通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_stop_and_notify",
      "verdict": "SUPPORT",
      "reason": "“并”明确连接停止和通知；未声明二者必须按先后顺序执行。",
      "sources": [
        {"quote": "停止并通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_notify_recipient",
      "verdict": "SUPPORT",
      "reason": "PM 是通知接收者，不能由此推出 PM 是通知动作执行者。",
      "sources": [
        {"quote": "通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_else_condition",
      "verdict": "SUPPORT",
      "reason": "前面的发现错误条件与后面的“否则”共同支持其否定分支约束形成文件。",
      "sources": [
        {"quote": "若发现 critical 错误", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "否则应形成 service-summary.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_generated_summary",
      "verdict": "SUPPORT",
      "reason": "形成动作的结果明确为 service-summary.md。",
      "sources": [
        {"quote": "形成 service-summary.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_restart_service",
      "verdict": "SUPPORT",
      "reason": "重启动作的对象明确为服务。",
      "sources": [
        {"quote": "重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r_forbid_restart",
      "verdict": "SUPPORT",
      "reason": "独立句“不得重启服务”支持任务范围内的重启禁止，没有仅限于某个条件分支的文字。",
      "sources": [
        {"quote": "不得重启服务", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "if_found",
      "verdict": "SUPPORT",
      "reason": "停止条件引用发现错误的状态，不产生独立发现义务。",
      "sources": [
        {"quote": "若发现 critical 错误，任务必须立即停止", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "if_found_notify",
      "verdict": "SUPPORT",
      "reason": "同一发现状态也是并列通知动作的条件。",
      "sources": [
        {"quote": "若发现 critical 错误，任务必须立即停止并通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "else_found_ref",
      "verdict": "SUPPORT",
      "reason": "作为 NOT 的内部操作数，引用“否则”所回指的发现状态；不是生成动作的独立肯定条件。",
      "sources": [
        {"quote": "若发现 critical 错误", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "否则应形成 service-summary.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "else_not_found",
      "verdict": "SUPPORT",
      "reason": "“否则”支持对前述发现条件取否定；未发现不能被扩张为证明不存在错误。",
      "sources": [
        {"quote": "若发现 critical 错误", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "否则应形成 service-summary.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    }
  ],
  "findings": [
    {
      "id": "f_immediate_scope",
      "kind": "COVERAGE_GAP",
      "candidate_ids": ["immediate", "r_immediate_stop", "notify", "r_stop_and_notify"],
      "sources": [
        {"quote": "任务必须立即停止并通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ],
      "reason": "“立即”明确覆盖停止，但其是否同时覆盖并列的通知存在作用域歧义。现有关系支持局部绑定，却没有保留可能同时要求立即通知的解释；不应将缺少通知时限关系当作通知无立即性要求的依据。"
    }
  ],
  "coverage": [
    {
      "region_id": "c1",
      "disposition": "AMBIGUOUS",
      "candidate_ids": [
        "pm", "organize", "check", "log", "critical_error", "found",
        "stop", "immediate", "notify", "generate", "summary", "restart",
        "service", "r_organizer", "r_check_complement", "r_checked_log",
        "r_discovered_error", "r_stop_condition", "r_stop_task",
        "r_immediate_stop", "r_notify_condition", "r_stop_and_notify",
        "r_notify_recipient", "r_else_condition", "r_generated_summary",
        "r_restart_service", "r_forbid_restart", "if_found",
        "if_found_notify", "else_found_ref", "else_not_found"
      ],
      "reason": "组织要求、检查对象、条件分支、停止、通知接收者、条件性文件产出和重启禁止均有文字依据。立即性的范围可能仅覆盖停止，也可能覆盖停止与通知，尚未保留该边界歧义。源文未明确检查、通知或生成的执行者，也未声明 ADMIN 分类或 WP；这些不能从角色名称或单根结构推断。"
    }
  ],
  "additional_candidates": {
    "nodes": [],
    "relations": [],
    "expressions": [],
    "unresolved": [
      {
        "id": "u_immediate_scope",
        "kind": "UNRESOLVED_SCOPE",
        "alternatives": [
          "立即性仅约束 stop",
          "立即性同时约束 stop 和 notify"
        ],
        "sources": [
          {"quote": "任务必须立即停止并通知 PM", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
        ],
        "reason": "副词“立即”位于并列谓语之前，停止的立即性明确，通知是否共享该时间约束不能唯一确定。"
      }
    ]
  }
}
